import { mkdir, writeFile, unlink } from 'node:fs/promises';
import { createReadStream } from 'node:fs';
import { resolve } from 'node:path';

// Keys are generated by the service, never taken from a client filename or URL.
export function createLocalStorage({ directory }) {
  const root = resolve(directory);
  function path(key) {
    if (!/^[a-f0-9-]{36}$/.test(key)) throw new Error('Invalid storage key');
    return resolve(root, key);
  }
  return {
    async put({ key, body }) { await mkdir(root, { recursive: true }); await writeFile(path(key), body, { flag: 'wx', mode: 0o600 }); },
    async get(key) { return createReadStream(path(key)); },
    async remove(key) { try { await unlink(path(key)); } catch (error) { if (error.code !== 'ENOENT') throw error; } }
  };
}

export async function createS3Storage({ bucket, region, endpoint, forcePathStyle = false, prefix = 'files/', client }) {
  if (!bucket || !region || !/^[a-zA-Z0-9/_-]*$/.test(prefix)) throw new Error('Invalid S3 configuration');
  const { S3Client, PutObjectCommand, GetObjectCommand, DeleteObjectCommand } = await import('@aws-sdk/client-s3');
  const s3 = client ?? new S3Client({ region, endpoint, forcePathStyle });
  const object = key => {
    if (!/^[a-f0-9-]{36}$/.test(key)) throw new Error('Invalid storage key');
    return { Bucket: bucket, Key: prefix + key };
  };
  return {
    async put({ key, body, contentType, ownerId }) {
      await s3.send(new PutObjectCommand({ ...object(key), Body: body, ContentType: contentType,
        ContentLength: body.length, ServerSideEncryption: 'AES256', Metadata: { owner: ownerId } }));
    },
    async get(key) { return (await s3.send(new GetObjectCommand(object(key)))).Body; },
    async remove(key) { await s3.send(new DeleteObjectCommand(object(key))); }
  };
}
